"use strict";(globalThis.webpackChunkmomentum_website=globalThis.webpackChunkmomentum_website||[]).push([[6921],{80658(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"category","label":"User Guide","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/momentum/docs/user_guide/getting_started","label":"Getting Started","docId":"user_guide/getting_started","unlisted":false},{"type":"link","href":"/momentum/docs/user_guide/creating_your_applications","label":"Creating Your Applications","docId":"user_guide/creating_your_applications","unlisted":false},{"type":"link","href":"/momentum/docs/user_guide/troubleshooting_guide","label":"Troubleshooting Guide","docId":"user_guide/troubleshooting_guide","unlisted":false},{"type":"link","href":"/momentum/docs/user_guide/character_files","label":"Character Files","docId":"user_guide/character_files","unlisted":false}]},{"type":"category","label":"Examples","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/momentum/docs/examples/viewers","label":"Viewers","docId":"examples/viewers","unlisted":false},{"type":"link","href":"/momentum/docs/examples/process_markers","label":"Process Markers","docId":"examples/process_markers","unlisted":false},{"type":"link","href":"/momentum/docs/examples/convert_model","label":"Convert Model","docId":"examples/convert_model","unlisted":false},{"type":"link","href":"/momentum/docs/examples/refine_motion","label":"Refine Motion (Post-process noisy tracking motion)","docId":"examples/refine_motion","unlisted":false},{"type":"link","href":"/momentum/docs/examples/export_rig","label":"Export Rig","docId":"examples/export_rig","unlisted":false},{"type":"link","href":"/momentum/docs/examples/apply_motion","label":"Apply Motion","docId":"examples/apply_motion","unlisted":false},{"type":"link","href":"/momentum/docs/examples/split_characters","label":"Split Characters","docId":"examples/split_characters","unlisted":false},{"type":"link","href":"/momentum/docs/examples/combine_characters","label":"Combine Characters","docId":"examples/combine_characters","unlisted":false}]},{"type":"category","label":"Developer Guide","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/momentum/docs/developer_guide/development_environment","label":"Development Environment","docId":"developer_guide/development_environment","unlisted":false},{"type":"link","href":"/momentum/docs/developer_guide/style_guide","label":"Style Guide","docId":"developer_guide/style_guide","unlisted":false}]}]},"docs":{"developer_guide/development_environment":{"id":"developer_guide/development_environment","title":"Development Environment","description":"Supported Environments","sidebar":"tutorialSidebar"},"developer_guide/style_guide":{"id":"developer_guide/style_guide","title":"Style Guide","description":"Momentum adheres to the following upstream standards, except when explicitly mentioned to override specific items:","sidebar":"tutorialSidebar"},"examples/apply_motion":{"id":"examples/apply_motion","title":"Apply Motion","description":"The applymotion example applies the motion of a motion file to the characters of a model file, and saves them in FBX, glTF/GLB or BVH format. Use the -m or --model option to specify the model file (.fbx, .glb, .gltf, .urdf, or .bvh), and the -d or --motion option to specify the motion file (.glb, .gltf, .fbx, or .bvh); a motion file of another format is an error. The files are read, and -p, -l and --character work, as described in Files and options shared by the tools; -p and -l apply to the character of the model file.","sidebar":"tutorialSidebar"},"examples/combine_characters":{"id":"examples/combine_characters","title":"Combine Characters","description":"The combinecharacters example saves the characters of several files with their motion to one file, for example a hand and the object it holds. Use the -i or --input option for each input file (.glb, .gltf, .fbx, .bvh, or .urdf), and -o or --out for the output file. The input files are read as described in Files and options shared by the tools. The motion of each character starts at the first frame of the output. A character with the name of an earlier character is saved with a numeric suffix, and a warning tells the new name. Use --markers to save the markers of a marker file (.c3d, .trc, .glb, .gltf, or .fbx) in the output.","sidebar":"tutorialSidebar"},"examples/convert_model":{"id":"examples/convert_model","title":"Convert Model","description":"The convert_model example demonstrates how to convert a character model and its associated animation file between FBX, glTF/GLB and BVH formats. Use the -m or --model option to specify the input model, followed by the path to the model file (.fbx, .glb, .gltf, .urdf, or .bvh). If no input model is provided, the tool will automatically read the animation from an existing glTF/GLB, FBX or BVH file given with -d or --motion; one of the two options is required. The input files are read as described in Files and options shared by the tools.","sidebar":"tutorialSidebar"},"examples/export_rig":{"id":"examples/export_rig","title":"Export Rig","description":"The exportrig example saves the parameter transform, the parameter limits and the locators of a character to .model and .locators files. Use the -m or --model option to specify the input character file (.fbx, .glb, .gltf, .urdf, or .bvh). The input file is read as described in Files and options shared by the tools, and -p and -l apply before the export. When the file has several characters, use --character to select the one to export.","sidebar":"tutorialSidebar"},"examples/process_markers":{"id":"examples/process_markers","title":"Process Markers","description":"Optical Marker based Body Tracking","sidebar":"tutorialSidebar"},"examples/refine_motion":{"id":"examples/refine_motion","title":"Refine Motion (Post-process noisy tracking motion)","description":"The input marker data may be noisy or contain missing data in a few frames. We can run a smoothing step on the entire sequence to fill in gaps and smooth out noise.","sidebar":"tutorialSidebar"},"examples/split_characters":{"id":"examples/split_characters","title":"Split Characters","description":"The splitcharacters example saves each character of a file, such as a hand and the object it holds, with its motion to a file of its own. Use the -i or --input option to specify the input file (.glb, .gltf, .fbx, or .bvh), and --out-dir for the output directory. Each file has the name of its character: ` replaces the characters other than letters, digits, -,  and ., a character without a name is saved as character, and a numeric suffix keeps the file names unique in any letter case. The output files have the format of the input file, unless --format selects another one (fbx, glb, gltf, or bvh`). The markers of the input file are not saved.","sidebar":"tutorialSidebar"},"examples/viewers":{"id":"examples/viewers","title":"Viewers","description":"Momentum supports various file formats for storing characters and motions. In this section, we demonstrate how to visualize these file formats using Momentum powered by Rerun.","sidebar":"tutorialSidebar"},"user_guide/character_files":{"id":"user_guide/character_files","title":"Character Files","description":"Momentum stores a character and its motion in a few file types, and each file type has a role. This page tells what each file holds and which file to change.","sidebar":"tutorialSidebar"},"user_guide/creating_your_applications":{"id":"user_guide/creating_your_applications","title":"Creating Your Applications","description":"This page guides you on how to create your own project that depends on the Momentum library.","sidebar":"tutorialSidebar"},"user_guide/getting_started":{"id":"user_guide/getting_started","title":"Getting Started","description":"This page guides you through the process of building Momentum (C++ library) and running the examples.","sidebar":"tutorialSidebar"},"user_guide/troubleshooting_guide":{"id":"user_guide/troubleshooting_guide","title":"Troubleshooting Guide","description":"Common issues and solutions when working with Momentum.","sidebar":"tutorialSidebar"}}}}')}}]);